$(document).ready(function(){
    if ($('.animsition').length) {
        $('.animsition').animsition({
            inClass             : 'fade-in',
            outClass            : 'fade-out',
            inDuration          : 400,
            outDuration         : 200,
            linkElement         : 'a[href]:not([target="_blank"]):not([href^="mailto\\:"]):not([href^="\\#"])',
            loading             : true,
            loadingParentElement: 'body',
            loadingClass        : 'animsition-loading',
            unSupportCss        : ['animation-duration', '-webkit-animation-duration', '-o-animation-duration'],
            overlay             : false,
            overlayClass        : 'animsition-overlay-slide',
            overlayParentElement: 'body'
        });
    }

        var options = {};

        options.ui = {
            bootstrap3: true,
            container: '.form-group',
            showVerdictsInsideProgressBar: true,
            viewports: {
                progress: '.pwstrength_viewport_progress',
                errors: '.pwstrength_viewport_errors'
            },
            showErrors: true
        };
        options.common = {
            debug: false,
            onLoad: function() {
                $('#messages').text('Start typing password');
            }
        };

        if ($('#password').length) {
            $('#password').pwstrength(options);
        }
        if ($('#new_password').length) {
            $('#new_password').pwstrength(options);
        }

        // Toggle password visibilidade
        function setupTogglePassword(toggleId, inputId) {
            const toggleBtn = document.getElementById(toggleId);
            const pwdInput = document.getElementById(inputId);
            
            if (toggleBtn && pwdInput) {
                const eyeIcon = toggleBtn.querySelector('i');
                toggleBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (pwdInput.type === 'password') {
                        pwdInput.type = 'text';
                        eyeIcon.classList.remove('fa-eye-slash');
                        eyeIcon.classList.add('fa-eye');
                    } else {
                        pwdInput.type = 'password';
                        eyeIcon.classList.remove('fa-eye');
                        eyeIcon.classList.add('fa-eye-slash');
                    }
                });
            }
        }
        
        setupTogglePassword('togglePassword', 'password');
        setupTogglePassword('toggleNewPassword', 'new_password');
        setupTogglePassword('toggleConfirmPassword', 'confirm_password');

        // Loading state no submit
        function setupLoadingForm(formId, btnId) {
            const formObj = document.getElementById(formId);
            const submitBtn = document.getElementById(btnId);
            if (formObj && submitBtn) {
                formObj.addEventListener('submit', function() {
                    submitBtn.classList.add('loading');
                    submitBtn.disabled = true;
                });
            }
        }
        
        setupLoadingForm('activateForm', 'submitBtn');
        setupLoadingForm('resetForm', 'submitBtn');

        // Custom password strength bar handler e clonagem de erros
        function setupPasswordInputEvents(inputId) {
            const pwdInput = document.getElementById(inputId);
            if (pwdInput) {
                pwdInput.addEventListener('input', function() {
                    const strengthBar = document.querySelector('.pwstrength_viewport_progress');
                    if (strengthBar) {
                        const val = this.value;
                        let strength = 0;
                        if (val.length > 0) strength += 20;
                        if (val.length >= 8) strength += 20;
                        if (val.match(/[a-z]/)) strength += 15;
                        if (val.match(/[A-Z]/)) strength += 15;
                        if (val.match(/[0-9]/)) strength += 15;
                        if (val.match(/[^a-zA-Z0-9]/)) strength += 15;
                        strength = Math.min(100, strength);
                        strengthBar.style.width = strength + '%';
                    }

                    setTimeout(function() {
                        const originalErrorList = document.querySelector('.password-field-container .error-list');
                        const targetErrorContainer = document.querySelector('.pwstrength_viewport_errors');
                        if (originalErrorList && targetErrorContainer) {
                            if (originalErrorList.innerHTML.trim() !== '') {
                                targetErrorContainer.innerHTML = '<ul>' + originalErrorList.innerHTML + '</ul>';
                            } else {
                                targetErrorContainer.innerHTML = '';
                            }
                        }
                    }, 50);
                });
            }
        }

        setupPasswordInputEvents('password');
        setupPasswordInputEvents('new_password');

    if ($('#group_bgcolor').length) {
        var elem = $('#group_bgcolor');

        elem.ColorPickerSliders({
            size: 'lg',
            placement: 'auto bottom',
            previewformat: 'hex',
            color: elem.attr('data-src'),
            swatches: ['#F44336', '#E91E63', '#9C27B0', '#673AB7', '#3F51B5', '#2196F3', '#009688', '#FF5722', '#795548', '#607D8B', '#000000'],
            customswatches: false,
            order: {}
        });

        $('button[type="reset"]').on('click', function(e){
            elem.trigger('colorpickersliders.updateColor', elem.attr('data-src'));
        });
    }
});


$(window).load(function(){


});